#!/usr/bin/env python
"""#192 evidence: what would a less-diluting acyclicity term do to the score?

Compares the current acyclicity axis (1 - tangle_ratio) against candidate
count-sensitive variants across the corpus + synthetic sizes. For each graph:

  - base overall under current vs each candidate (clean-graph rank impact)
  - inject ONE 2-cycle, measure overall delta + survival under current vs each
    candidate (does the candidate actually fix the single-edge dilution?)
  - the candidate's penalty on the CLEAN graph vs module count (does it punish
    large healthy codebases for proportionally-tiny pathology?)

Prints a compact summary; raw rows kept out of context.
"""
from __future__ import annotations
import sys, math
from pathlib import Path

ROOT = Path("/Users/hosanglee/archy")
sys.path.insert(0, str(ROOT / "src"))

import networkx as nx
from archy.cycles import find_cycles
from archy.graph import build_graph
from archy import score as S

REPLAY = ROOT / "bench" / "replay_cache"
SYN = (300, 1500, 5000)


def internal_graph(root: Path) -> nx.DiGraph:
    g = build_graph(root)
    g.remove_nodes_from([n for n, d in g.nodes(data=True) if d.get("external")])
    return g


def synthetic_dag(n: int) -> nx.DiGraph:
    g = nx.DiGraph()
    for i in range(n):
        g.add_node(f"m{i}")
    for i in range(1, n):
        g.add_edge(f"m{i}", f"m{i-1}", kinds=("import",), lines=(1,))
        if i >= 2:
            g.add_edge(f"m{i}", f"m{i-2}", kinds=("import",), lines=(1,))
    return g


def inject_two_cycle(g):
    cyclic = {m for c in find_cycles(g) for m in c.modules}
    for u, v in sorted(g.edges()):
        if u in cyclic or v in cyclic or g.has_edge(v, u):
            continue
        g1 = g.copy()
        g1.add_edge(v, u, kinds=("import",), lines=(1,))
        scc = next(s for s in nx.strongly_connected_components(g1) if u in s)
        if scc == {u, v}:
            return g1, (u, v)
    raise RuntimeError("no site")


# --- candidate acyclicity formulas (input: tangle_ratio, cycle_count, n) ----
# current: 1 - tangle_ratio
def acy_current(tr, cc, n):
    return 1.0 - tr

# A: linear count penalty added to proportion (beta per SCC), clamped
def acy_countlin(tr, cc, n, beta=0.05):
    return 1.0 - min(1.0, tr + beta * cc)

# B: max of proportion and a per-cycle floor (each cycle worth `delta`, capped)
def acy_floor(tr, cc, n, delta=0.05, cap=0.5):
    return 1.0 - max(tr, min(cap, delta * cc))

# C: log-count blend
def acy_logcount(tr, cc, n, gamma=0.06):
    return 1.0 - min(1.0, tr + gamma * math.log1p(cc))

CANDS = {"current": acy_current, "A_countlin": acy_countlin,
         "B_floor": acy_floor, "C_logcount": acy_logcount}


def axes_and_inputs(g):
    """Return (mod, acy_current, dep, eq, cpx, tangle_ratio, cycle_count, n)."""
    mod, _, _ = S.compute_modularity(g)
    acy, cc, tr = S.compute_acyclicity(g)
    dep, _ = S.compute_depth(g)
    eq, _ = S.compute_equality(g)
    fn, tot, mx, mean = S._cc_stats(g)
    cpx = S.compute_complexity(mean, fn)
    n = g.number_of_nodes()
    return mod, acy, dep, eq, cpx, tr, cc, n


def overall_with(mod, acyv, dep, eq, cpx):
    return (mod * acyv * dep * eq * cpx) ** 0.2


def row_for(g, label):
    mod, acy, dep, eq, cpx, tr, cc, n = axes_and_inputs(g)
    base = {}
    for name, f in CANDS.items():
        av = f(tr, cc, n)
        base[name] = {"acy": av, "overall": overall_with(mod, av, dep, eq, cpx)}
    # inject one 2-cycle
    try:
        g1, _ = inject_two_cycle(g)
    except RuntimeError:
        return None
    mod1, acy1, dep1, eq1, cpx1, tr1, cc1, n1 = axes_and_inputs(g1)
    inj = {}
    for name, f in CANDS.items():
        av0 = f(tr, cc, n)
        av1 = f(tr1, cc1, n1)
        o0 = overall_with(mod, av0, dep, eq, cpx)
        o1 = overall_with(mod1, av1, dep1, eq1, cpx1)
        d_acy = av1 - av0
        d_ov = o1 - o0
        inj[name] = {"d_acy": d_acy, "d_overall": d_ov,
                     "survival": abs(d_ov) / abs(d_acy) if d_acy else 0.0,
                     "sign_ok": d_ov < 0}
    return {"label": label, "n": n, "cc": cc, "tr": tr, "base": base, "inj": inj}


def main():
    graphs = [(synthetic_dag(n), f"syn-{n}") for n in SYN]
    if REPLAY.is_dir():
        for repo in sorted(p for p in REPLAY.iterdir() if p.is_dir()):
            g = internal_graph(repo)
            if g.number_of_edges():
                graphs.append((g, repo.name))
    rows = [r for r in (row_for(g, l) for g, l in graphs) if r]

    # 1) base-graph stats: cycle_count + how candidates penalize CLEAN graphs by size
    print("=== CLEAN-GRAPH base acyclicity by candidate (and stock cycle_count) ===")
    print(f"{'graph':14}{'n':>6}{'cc':>4}{'tr':>7}  " +
          "".join(f"{k:>12}" for k in CANDS))
    for r in sorted(rows, key=lambda r: -r["n"]):
        print(f"{r['label']:14}{r['n']:>6}{r['cc']:>4}{r['tr']:>7.3f}  " +
              "".join(f"{r['base'][k]['acy']:>12.4f}" for k in CANDS))

    # 2) inject-cycle survival per candidate
    print("\n=== INJECT one 2-cycle: overall survival (|d_overall|/|d_acy|) ===")
    print(f"{'graph':14}{'n':>6}  " + "".join(f"{k:>12}" for k in CANDS))
    for r in sorted(rows, key=lambda r: -r["n"]):
        print(f"{r['label']:14}{r['n']:>6}  " +
              "".join(f"{r['inj'][k]['survival']:>11.1%} " for k in CANDS))

    print("\n=== INJECT: overall delta SIGN correct (negative)? ===")
    for k in CANDS:
        bad = [r["label"] for r in rows if not r["inj"][k]["sign_ok"]]
        print(f"  {k:12}: wrong-sign on {len(bad)}/{len(rows)} graphs" +
              (f" -> {bad}" if bad else ""))

    # 3) corpus rank stability vs current (Spearman of base overall)
    import statistics as st
    def spearman(a, b):
        def rank(v):
            order = sorted(range(len(v)), key=lambda i: v[i]); rk = [0]*len(v)
            for p, i in enumerate(order): rk[i] = p
            return rk
        ra, rb = rank(a), rank(b)
        ma, mb = st.mean(ra), st.mean(rb)
        cov = sum((x-ma)*(y-mb) for x, y in zip(ra, rb))
        da = sum((x-ma)**2 for x in ra) ** .5
        db = sum((y-mb)**2 for y in rb) ** .5
        return cov/(da*db) if da and db else 1.0
    cur = [r["base"]["current"]["overall"] for r in rows]
    print("\n=== CORPUS rank stability: Spearman(base overall) vs current ===")
    for k in CANDS:
        if k == "current": continue
        ov = [r["base"][k]["overall"] for r in rows]
        print(f"  {k:12}: rho={spearman(cur, ov):.3f}")

    # 4) does the candidate penalize LARGE healthy graphs? acy drop vs n, on
    #    clean graphs that ALREADY carry cycles (cc>0)
    print("\n=== CLEAN-graph acyclicity drop vs current, on repos with stock cycles ===")
    print(f"{'graph':14}{'n':>6}{'cc':>4}  " +
          "".join(f"{k:>12}" for k in CANDS if k != "current"))
    for r in sorted((r for r in rows if r["cc"] > 0), key=lambda r: -r["n"]):
        print(f"{r['label']:14}{r['n']:>6}{r['cc']:>4}  " +
              "".join(f"{r['base'][k]['acy']-r['base']['current']['acy']:>+12.4f}"
                      for k in CANDS if k != "current"))


if __name__ == "__main__":
    main()

